package ttviet.dao;import java.sql.*;import javax.swing.table.DefaultTableModel;public class TableDAO{public static DefaultTableModel load(){DefaultTableModel m=new DefaultTableModel(new String[]{"Mã bàn","Tên bàn","Trạng thái"},0);try(Connection c=DB.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,table_name,status FROM cafe_tables ORDER BY id")){while(r.next())m.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3)});}catch(SQLException e){javax.swing.JOptionPane.showMessageDialog(null,e.getMessage());}return m;}}